import{z as A,x as m,o as n,c as h,q as s,j as i,D as t,d as l,s as r,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"FlashAttention","description":"","frontmatter":{"title":"FlashAttention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/flashattention.md","filePath":"llm/flashattention.md","lastUpdated":1791063341000}'),d={name:"llm/flashattention.md"};function B(p,a,f,M,c,u){const o=m("Mermaid");return n(),h("div",null,[a[2]||(a[2]=s('<h1 id="flashattention" tabindex="-1">FlashAttention <a class="header-anchor" href="#flashattention" aria-label="Permalink to &quot;FlashAttention&quot;">​</a></h1><div class="epigraph"><p>我们提出一种输入输出感知的精确注意力算法，用分块减少 GPU 高带宽存储与片上 SRAM 之间的读写，而不把 softmax 注意力改成近似。</p><footer>—— Dao et al., FlashAttention, NeurIPS 2022</footer></div><p><a href="/llm/splitfuse">上一课</a>把混合批次的前向尺寸写清楚：每一拍里可以同时有前填切片与解码 token。无论这一拍的查询有多长，注意力仍是 <a href="/llm/sdpa">SDPA</a>，公式这里不再写。<a href="/llm/attention-quadratic-cost">二次复杂度</a>已经说明：稠密 softmax 的阶是 \\(O(n^2 d)\\)，朴素实现还会把 \\(S\\) 和 \\(A\\) 物化在 HBM 上。本课默认这两件事成立，只补 IO：精确结果可以不经过这张完整的 \\(n\\times n\\) 表。FlashAttention 利用 GPU 存储层次——HBM 大而慢、SRAM 小而快——按块装入 \\(Q,K,V\\)，在片上完成打分、归一化与加权。变的是搬运，不是公式。混合批次吃不吃得饱，最终仍取决于这个核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/attention-quadratic-cost">二次复杂度</a>已经把内存墙写清楚：写出 \\(S\\)、\\(A\\) 再读入做 \\(AV\\)，HBM 访问是 \\(O(n^2)\\)，算术单元闲着等分数矩阵；训练再存 \\(A\\)，显存按 \\(n^2\\) 涨。缺口不是再解释为什么二次，而是：同一条 softmax 注意力，能否少搬、少存，数值仍与朴素算法一致。近似注意力可以降阶，但改的是模型，预训练对不上。问题因此是 IO 感知的精确算法，而不是新的相容性函数。</p><p><span class="marginnote">直觉类比：HBM 与 SRAM 的关系像书架和手边桌面。书架（HBM）装得下整个图书馆，但每取一本都要走一趟；桌面（SRAM）只摊得开几页，取用却几乎不花时间。FlashAttention 做的就是少跑图书馆——把要用的几页一次搬上桌，用尽再换。</span></p><h3 id="在线-softmax-为何必要" tabindex="-1">在线 softmax 为何必要 <a class="header-anchor" href="#在线-softmax-为何必要" aria-label="Permalink to &quot;在线 softmax 为何必要&quot;">​</a></h3><p>softmax 的分母依赖整行。若按键块逐块计算，块 \\(j\\) 的局部 \\(\\mathrm{softmax}(S_{:,j})\\) 不能直接与块 \\(j+1\\) 的结果相加，因为两边的最大值和指数和不同。必须维护行统计量：到目前为止的最大值 \\(m\\)，以及按该最大值缩放后的指数和 \\(\\ell\\)。来了新块，若新最大值更大，旧的加权输出与 \\(\\ell\\) 要按指数差重缩放，再累加新块贡献。这套递推（在线 softmax）让分块与精确归一化相容。缺了它，分块注意力就是错的。</p><p><span class="marginnote">FlashAttention 不是「更快的近似」。作者强调 exact：在合理浮点误差内与物化算法同类。速度来自少访问 HBM，以及把 softmax 与矩阵乘融进同一核，而不是丢掉序对。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 \\(Q\\) 按行切成块（每块 \\(B_r\\) 条查询），\\(K,V\\) 按列切成块（每块 \\(B_c\\) 个键值）。对每个查询块，循环扫过所有键值块：从 HBM 装入当前 \\(K_j,V_j\\) 到 SRAM，与驻留的 \\(Q_i\\) 做乘加，更新 \\(m,\\ell\\) 与输出累加器 \\(O_i\\)。扫完键值后，\\(O_i\\) 已是该查询块的最终加权，写回 HBM。SRAM 容量限制 \\(B_r,B_c\\)；理论分析给出 HBM 访问可降到与 \\(n,d\\) 及片上块大小相关的更低阶主导项——仍含二次计算，但二次张量不再落盘。</p><p>因果掩码在块级即可跳过严格位于下三角之外的键块，大约减半前填计算。Padding 同理。反向不保存 \\(A\\)：用保存的 \\(Q,K,V\\)、输出和归一化统计量，再扫一遍块把注意力重算出来以传播梯度。用更多算术换更少存储，符合「计算相对搬运更便宜」。这与层间梯度检查点是不同粒度：这里重算的是注意力核内部，对象是 \\(n\\times n\\) 中间量。</p><h3 id="融合核与实现边界" tabindex="-1">融合核与实现边界 <a class="header-anchor" href="#融合核与实现边界" aria-label="Permalink to &quot;融合核与实现边界&quot;">​</a></h3><p>算法要落成一个（或少数几个）CUDA 核，才能避免块循环把中间分数写回 HBM。核内还要把 softmax 的减最大值、指数保持在较高精度，以免半精度溢出——这与 SDPA 的数值卫生是同一件事，只是发生在 SRAM 里。头维度、是否因果、是否有 dropout、是否变长序列，都会派生出不同模板。第一代实现把并行主要放在 batch 与头维：序列很长、batch 与头数不够时，占用率上不去。这是 <a href="/llm/flashattention-2">FlashAttention-2</a> 要补的工作划分，不是 2022 年论文已经做完的事。</p>',14)),(n(),i(E,null,{default:t(()=>[r(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20HBM%5B%22HBM%3A%20Q%20K%20V%22%5D%20--%3E%20TILE%5B%22%E8%A3%85%E5%85%A5%20SRAM%20%E5%88%86%E5%9D%97%22%5D%0A%20%20TILE%20--%3E%20GEMM%5B%22%E5%9D%97%E5%86%85%20QK%20%E4%B8%8E%20PV%22%5D%0A%20%20GEMM%20--%3E%20ON%5B%22%E5%9C%A8%E7%BA%BF%E6%9B%B4%E6%96%B0%20m%20%E2%84%93%20O%22%5D%0A%20%20ON%20--%3E%20TILE%0A%20%20ON%20--%3E%20OUT%5B%22%E5%86%99%E5%9B%9E%20O%20%E4%B8%8E%E7%BB%9F%E8%AE%A1%E9%87%8F%22%5D%0A%20%20OUT%20--%3E%20HBM2%5B%22HBM%20%E4%B8%8A%E6%97%A0%E5%AE%8C%E6%95%B4%20A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"IO 收益来自算术强度。每个 \\(K_j\\) 块被装入后，与当前 \\(Q_i\\) 的 \\(B_r\\) 条查询做完再换下一块；查询块驻留期间，键值块被充分复用。物化路线则是：写出 \\(n\\times n\\)，几乎没有对 \\(S\\) 的数据复用就进入下一阶段。FlashAttention 把三阶段合成对 SRAM 的多次复用，HBM 只看见 \\(O(nd)\\) 量级的主张量进出，外加统计量。\\(n\\) 越大、相对片上块越「需要很多键值块」时，相对朴素实现的加速通常越明显；极短序列上核启动与融合开销可能让它比不上物化 GEMM。",-1)),a[5]||(a[5]=e("p",null,"精确性来自行统计量的结合律：两段键的 \\((m,\\ell,O)\\) 可以合成全局的 \\((m,\\ell,O)\\)，等价于一次性 softmax。浮点顺序不同会带来尾差，但目标是与标准实现同级误差，而不是另定义一种注意力。Dropout 要在重算时用同一掩码，否则反向对不上；训练核因此比推理核更重。",-1)),(n(),i(E,null,{default:t(()=>[r(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20C1%5B%22%E5%9D%97%201%20%E7%9A%84%E5%88%86%E6%95%B0%22%5D%20--%3E%20S1%5B%22%E5%B1%80%E9%83%A8%E7%BB%9F%E8%AE%A1%20m1%2C%20%E2%84%931%2C%20O1%22%5D%0A%20%20C2%5B%22%E5%9D%97%202%20%E7%9A%84%E5%88%86%E6%95%B0%22%5D%20--%3E%20S2%5B%22%E5%B1%80%E9%83%A8%E7%BB%9F%E8%AE%A1%20m2%2C%20%E2%84%932%2C%20O2%22%5D%0A%20%20S1%20--%3E%20M%5B%22%E5%8F%96%E5%85%A8%E5%B1%80%E6%9C%80%E5%A4%A7%20m%20%3D%20max(m1%2C%20m2)%22%5D%0A%20%20S2%20--%3E%20M%0A%20%20M%20--%3E%20R%5B%22%E6%8C%89%E6%8C%87%E6%95%B0%E5%B7%AE%E9%87%8D%E7%BC%A9%E6%94%BE%20O%20%E4%B8%8E%20%E2%84%93%22%5D%0A%20%20R%20--%3E%20F%5B%22%E5%90%88%E6%88%90%E5%85%A8%E5%B1%80%E7%BB%93%E6%9E%9C%EF%BC%8C%E7%AD%89%E4%BB%B7%E4%B8%80%E6%AC%A1%E7%AE%97%E5%AE%8C%E6%95%B4%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">这一步是整个 FlashAttention 的数学地基：softmax 的行统计量满足结合律，所以「先算一半再算另一半」与「一次算完整行」结果一致。如果哪天你要自己写分块注意力，合并统计量时漏掉重缩放，输出不会报错，只会悄悄错——这正是初学者最容易踩的坑。</span></p><p><span class="marginnote">把 FlashAttention 理解成「注意力终于线性了」是错的。HBM 占用可以对 \\(n\\) 接近线性（不存 \\(A\\)），计算仍是 \\(\\Theta(n^2 d)\\)。长上下文的时间墙还在，只是不再先被显存墙以 \\(n^2\\) 的方式击倒。</span></p><h3 id="与服务侧解码的错位" tabindex="-1">与服务侧解码的错位 <a class="header-anchor" href="#与服务侧解码的错位" aria-label="Permalink to &quot;与服务侧解码的错位&quot;">​</a></h3><p>训练和前填的查询长度与键长度同阶，分块沿两维都有活干。解码时查询长度往往为 1，并行度只剩 batch×头数，第一代内核容易吃不满 SM，加速从「少写 \\(n\\times n\\)」变成「小核能不能喂饱机器」。这要靠 <a href="/llm/flashdecoding">FlashDecoding</a> 沿 KV 维再切，而不是指望 2022 年的前向循环自动变快。Paged KV 的非连续块也需要核支持页表，那是 <a href="/llm/paged-attention">PagedAttention</a> 与注意力内核的接口问题，FlashAttention 原文假定的是常规布局。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FlashAttention 不改变模型质量合同，但改变工程合同：必须有对应头维与掩码的核；没有核时框架会回退到物化实现，长序列再次 OOM。反向重算增加训练步时，换来的是能跑的 \\(n\\)。若 SRAM 不够大、头维过宽，块变小，IO 收益下降。窗口、稀疏、线性注意力若仍走自己的连通性，不能假冒成 FlashAttention；它们可以借用分块实现，但那是另一条算法。</p><p><span class="marginnote">为什么重要：回退通常是静默的——形状冷门（如 \\(d=72\\)）或用了特殊掩码时，框架不报「不支持」，而是悄悄换回物化实现，显存立刻按 \\(n^2\\) 涨，表现为训练到一半 OOM。排障时应先确认核真的被调用（打印日志或用 profiler），再去怀疑模型本身。</span></p><p>不要用某一张 A100 上相对 PyTorch 朴素实现的「2–4×」去推断今天所有硬件。基线、序列长度、是否因果、是否已经融合 GEMM，都会改倍数。后续 FA2/FA3 的意义正是：同一算法家族在占用率与新硬件异步单元上还有很大头。2022 年论文解决的是 IO 感知与精确分块这一层。</p><p><span class="marginnote">引用时应写 Dao, Fu, Ermon, Rudra, Ré，NeurIPS 2022。不要把后来的 FA2 工作划分或 FA3 的 TMA/WGMMA 写回这篇论文。本系列后两篇分开记。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FlashAttention 用 SRAM 分块与在线 softmax 计算精确 SDPA，避免物化 \\(n\\times n\\) 分数与权重。</li><li>渐近计算仍二次；主要收益是 HBM 流量与训练激活显存。</li><li>反向重算注意力块，用算术换存储。</li><li>并行原语以 batch 与头为主，长序列小 batch 时占用率有限，留给后续版本。</li><li>解码短查询、分页 KV、新硬件异步指令，都不在 2022 年论文的核心命题里。</li><li>与近似注意力不同，它不改预训练相容性。</li><li>出处：Dao et al., <em>FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness</em>, NeurIPS 2022。</li></ul>',11))])}const D=A(d,[["render",B]]);export{S as __pageData,D as default};
